class Solution:
    def kthDigit(self, k):
        if k <= 9:
            return k
        t = k - 9
        b, pos = divmod(t - 1, 20)
        blk = b + 1
        idx, par = divmod(pos, 2)
        num = 10 * blk + idx if blk % 2 == 0 else 10 * blk + 9 - idx
        return num // 10 if par == 0 else num % 10

c.cpp:
class Solution {
public:
    long long kthDigit(long long k) {
        if (k <= 9) return k;
        long long t = k - 9;
        long long b = (t - 1) / 20, pos = (t - 1) % 20;
        long long blk = b + 1, idx = pos / 2;
        long long num = (blk % 2 == 0) ? 10 * blk + idx : 10 * blk + 9 - idx;
        return (pos % 2 == 0) ? num / 10 : num % 10;
    }
};

