var kthDigit = function(k) {
    if (k <= 9) return k;
    const t = k - 9;
    const b = Math.floor((t - 1) / 20), pos = (t - 1) % 20;
    const blk = b + 1, idx = Math.floor(pos / 2);
    const num = blk % 2 === 0 ? 10 * blk + idx : 10 * blk + 9 - idx;
    return pos % 2 === 0 ? Math.floor(num / 10) : num % 10;
};
